class MajorityChecker {
    private final int n;
    private final int[] candidate,balance;
    private final Map<Integer,List<Integer>> positions=new HashMap<>();
    public MajorityChecker(int[] arr){
        n=arr.length;
        candidate=new int[4*n];
        balance=new int[4*n];
        for(int i=0;i<n;i++)positions.computeIfAbsent(arr[i],key->new ArrayList<>()).add(i);
        build(1,0,n-1,arr);
    }
    private void build(int node,int left,int right,int[] arr){
        if(left==right){
            candidate[node]=arr[left];
            balance[node]=1;
            return;
        }
        int middle=(left+right)/2;
        build(node*2,left,middle,arr);
        build(node*2+1,middle+1,right,arr);
        int[] merged=merge(candidate[node*2],balance[node*2],candidate[node*2+1],balance[node*2+1]);
        candidate[node]=merged[0];
        balance[node]=merged[1];
    }
    private int[] merge(int a,int aCount,int b,int bCount){
        if(a==b)return new int[]{
            a,aCount+bCount
        };
        return aCount>=bCount?new int[]{
            a,aCount-bCount
        }:new int[]{
            b,bCount-aCount
        };
    }
    private int[] rangeCandidate(int node,int left,int right,int queryLeft,int queryRight){
        if(queryLeft<=left&&right<=queryRight)return new int[]{
            candidate[node],balance[node]
        };
        int middle=(left+right)/2;
        if(queryRight<=middle)return rangeCandidate(node*2,left,middle,queryLeft,queryRight);
        if(queryLeft>middle)return rangeCandidate(node*2+1,middle+1,right,queryLeft,queryRight);
        int[] a=rangeCandidate(node*2,left,middle,queryLeft,queryRight),b=rangeCandidate(node*2+1,middle+1,right,queryLeft,queryRight);
        return merge(a[0],a[1],b[0],b[1]);
    }
    private int lowerBound(List<Integer> list,int target){
        int left=0,right=list.size();
        while(left<right){
            int middle=(left+right)/2;
            if(list.get(middle)<target)left=middle+1;
            else right=middle;
        }
        return left;
    }
    public int query(int left,int right,int threshold){
        int value=rangeCandidate(1,0,n-1,left,right)[0];
        List<Integer> list=positions.get(value);
        int count=lowerBound(list,right+1)-lowerBound(list,left);
        return count>=threshold?value:-1;
    }
}

