class MajorityChecker(arr:IntArray) {
    private val n=arr.size;
    private val candidate=IntArray(4*n);
    private val balance=IntArray(4*n);
    private val positions=mutableMapOf<Int,MutableList<Int>>();
    init{
        for(i in arr.indices)positions.getOrPut(arr[i]){
            mutableListOf()
        }.add(i);
        build(1,0,n-1,arr)
    };
    private fun build(node:Int,left:Int,right:Int,arr:IntArray){
        if(left==right){
            candidate[node]=arr[left];
            balance[node]=1;
            return
        };
        val middle=(left+right)/2;
        build(node*2,left,middle,arr);
        build(node*2+1,middle+1,right,arr);
        val merged=merge(candidate[node*2],balance[node*2],candidate[node*2+1],balance[node*2+1]);
        candidate[node]=merged[0];
        balance[node]=merged[1]
    };
    private fun merge(a:Int,aCount:Int,b:Int,bCount:Int):IntArray=if(a==b)intArrayOf(a,aCount+bCount) else if(aCount>=bCount)intArrayOf(a,aCount-bCount) else intArrayOf(b,bCount-aCount);
    private fun rangeCandidate(node:Int,left:Int,right:Int,queryLeft:Int,queryRight:Int):IntArray{
        if(queryLeft<=left&&right<=queryRight)return intArrayOf(candidate[node],balance[node]);
        val middle=(left+right)/2;
        if(queryRight<=middle)return rangeCandidate(node*2,left,middle,queryLeft,queryRight);
        if(queryLeft>middle)return rangeCandidate(node*2+1,middle+1,right,queryLeft,queryRight);
        val a=rangeCandidate(node*2,left,middle,queryLeft,queryRight);
        val b=rangeCandidate(node*2+1,middle+1,right,queryLeft,queryRight);
        return merge(a[0],a[1],b[0],b[1])
    };
    private fun lowerBound(list:List<Int>,target:Int):Int{
        var left=0;
        var right=list.size;
        while(left<right){
            val middle=(left+right)/2;
            if(list[middle]<target)left=middle+1 else right=middle
        };
        return left
    };
    fun query(left:Int,right:Int,threshold:Int):Int{
        val value=rangeCandidate(1,0,n-1,left,right)[0];
        val list=positions[value]!!;
        val count=lowerBound(list,right+1)-lowerBound(list,left);
        return if(count>=threshold)value else -1
    }
}

